<?php
function seed_addons_gallery($url,$layout='grid',$caption='card',$initial=4){
 $slug=$initial<4?'paged-gallery':($caption==='layout_3'?'search-gallery':($layout==='masonry'?'masonry-gallery':'filtered-gallery'));$old=get_page_by_path($slug);$id=wp_insert_post(['ID'=>$old?$old->ID:0,'post_type'=>'page','post_status'=>'publish','post_title'=>'Filtered Gallery','post_name'=>$slug]);
 $images=get_posts(['post_type'=>'attachment','post_mime_type'=>'image','numberposts'=>1]);if(!$images){$uploads=wp_upload_dir();$file=$uploads['path'].'/studio.png';if(!is_file($file))throw new RuntimeException('Fixture image missing');$image=wp_insert_attachment(['post_title'=>'Workshop collection','post_mime_type'=>'image/png','post_status'=>'inherit'],$file);require_once ABSPATH.'wp-admin/includes/image.php';wp_update_attachment_metadata($image,wp_generate_attachment_metadata($image,$file));}else{$image=$images[0]->ID;}
 $items=[];foreach(['Chair'=>'Furniture','Lamp'=>'Lighting','Desk'=>'Furniture','Pendant'=>'Lighting'] as $title=>$category){$items[]=['_id'=>'gg'.count($items).'0001','eael_fg_gallery_item_name'=>$title,'eael_fg_gallery_control_name'=>$category,'eael_fg_gallery_item_content'=>'<p>'.$title.' from our workshop.</p>'.($layout==='masonry'?str_repeat('<p>Made with care for everyday use.</p>',['Chair'=>2,'Lamp'=>0,'Desk'=>3,'Pendant'=>1][$title]):''),'eael_fg_gallery_img'=>['id'=>$image,'url'=>wp_get_attachment_url($image)],'eael_fg_gallery_lightbox'=>'','eael_fg_gallery_link'=>''];}
 $widget=['id'=>'gg10001','elType'=>'widget','widgetType'=>'eael-filterable-gallery','settings'=>['eael_fg_caption_style'=>$caption,'eael_fg_grid_style'=>$layout,'eael_fg_grid_item_height'=>['unit'=>'px','size'=>200],'columns'=>'3','columns_tablet'=>'2','columns_mobile'=>'1','eael_fg_items_to_show'=>$initial,'pagination'=>$initial<4?'yes':'false','images_per_page'=>2,'eael_search_among_all'=>$initial<4?'yes':'','filter_enable'=>'yes','eael_fg_all_label_text'=>'All','eael_fg_show_popup'=>'none','eael_fg_controls'=>[['_id'=>'ff10001','eael_fg_control'=>'Furniture'],['_id'=>'ff10002','eael_fg_control'=>'Lighting']],'eael_fg_gallery_items'=>$items],'elements'=>[]];
 $data=[['id'=>'ss10001','elType'=>'section','settings'=>[],'elements'=>[['id'=>'cc10001','elType'=>'column','settings'=>['_column_size'=>100],'elements'=>[$widget]]]]];
 update_post_meta($id,'_elementor_edit_mode','builder');update_post_meta($id,'_elementor_version',ELEMENTOR_VERSION);update_post_meta($id,'_elementor_data',wp_slash(wp_json_encode($data)));update_post_meta($id,'_wp_page_template','elementor_header_footer');\Elementor\Core\Files\CSS\Post::create($id)->update();
 return ['id'=>$id,'url'=>get_permalink($id),'widget'=>'eael-filterable-gallery','layout'=>$caption.'/'.$layout,'items'=>4,'categories'=>['Furniture','Lighting']];
}
